        'bazargan'       => ['name' => 'بازرگان',        'p' => ['بازرگان مهم‌ترین گذرگاه زمینی ایران و ترکیه است؛ شرکت‌های حمل‌ونقل بین‌المللی، ترخیص‌کاران و صرافی‌هایش با طرف‌های خارجی کار می‌کنند و ویترین آنلاین حرفه‌ای برایشان اعتبار تجاری است، نه تجمل. صفحهٔ قدیمی ما برای بازرگان سال‌ها در گوگل رتبه داشت — این نسخهٔ به‌روز همان تعهد است.', 'سایت شرکت‌های بازرگان را دوزبانه و با تمرکز بر اعتمادسازی می‌سازیم: مجوزها، سابقه، مسیرهای فعال و راه تماس مستقیم.']],
        'sardasht'       => ['name' => 'سردشت',          'p' => ['سردشت با طبیعت کم‌نظیر و بازارچهٔ مرزی‌اش، هم ظرفیت گردشگری دارد هم تجارت محلی فعال. اقامتگاه‌های بوم‌گردی و کسب‌وکارهای مرزی سردشت با معرفی آنلاین درست، مشتری را از سراسر کشور جذب می‌کنند.', 'برای مجموعه‌های سردشت، سایت سبک و سریع می‌سازیم که با اینترنت ضعیف هم خوب باز شود — و عکس‌محور، چون طبیعت سردشت خودش فروشنده است.']],
        'oshnavieh'      => ['name' => 'اشنویه',         'p' => ['اشنویه در دامنهٔ کوه‌های مرزی، کشاورزی پررونق و بازارچهٔ فعال دارد. کسب‌وکارهای محلی — از فروش محصولات کشاورزی تا خدمات — با یک سایت ساده و درست می‌توانند در جستجوهای منطقه بدون رقیب جدی دیده شوند.', 'پروژه‌های اشنویه را با بسته‌های شروع اقتصادی و پشتیبانی از راه دور اجرا می‌کنیم؛ جلسهٔ حضوری در صورت نیاز قابل هماهنگی است.']],
        'poldasht'       => ['name' => 'پلدشت',          'p' => ['پلدشت در شمال استان و کنار ارس، منطقهٔ کشاورزی و دامداری فعالی است. تولیدکنندگان محلی با معرفی آنلاین محصولاتشان می‌توانند خریداران عمده را مستقیم پیدا کنند — بدون واسطه‌هایی که حاشیهٔ سود را می‌برند.', 'برای کسب‌وکارهای پلدشت سایت معرفی محصول با امکان سفارش‌گیری ساده می‌سازیم؛ کار از راه دور شروع می‌شود و آموزش، تلفنی و تصویری است.']],
        'showt'          => ['name' => 'شوط',            'p' => ['شوط شهرستان جوان شمال استان است و اقتصادش بر کشاورزی و تجارت خرد می‌چرخد. برای کسب‌وکار شوطی، سایت خوب یعنی دیده‌شدن در جستجوهایی که هنوز هیچ رقیبی برایشان صفحه نساخته — فرصتی که در شهرهای بزرگ سال‌هاست تمام شده.', 'بسته‌های شروع ما برای شهرهای کوچک استان طراحی شده: هزینهٔ منطقی، تحویل سریع و پشتیبانی واقعی از مرکز استان.']],
        'chaldoran'      => ['name' => 'چالدران',        'p' => ['چالدران — سرزمین دشت تاریخی و مرز مشترک با ترکیه — اقتصادی مبتنی بر دامداری، کشاورزی و تجارت مرزی دارد. کسب‌وکارهای محلی و مجموعه‌های گردشگری تاریخی آن با حضور آنلاین می‌توانند مخاطبی فراتر از شهرستان پیدا کنند.', 'پروژه‌های چالدران را از راه دور با پشتیبانی کامل اجرا می‌کنیم و برای مجموعه‌های گردشگری، روایت تاریخی منطقه را محور محتوا قرار می‌دهیم.']],
        'qarah-ziaeddin' => ['name' => 'قره‌ضیاءالدین',   'p' => ['قره‌ضیاءالدین (مرکز شهرستان چایپاره) منطقهٔ کشاورزی حاصلخیزی است که تولیداتش به بازارهای استانی می‌رود. تولیدکنندگان و اصناف محلی با یک معرفی آنلاین ساده می‌توانند خریداران را مستقیم به خودشان برسانند.', 'صفحهٔ قدیمی سرورنت برای این شهر سال‌ها در نتایج جستجو حاضر بود؛ این صفحه ادامهٔ همان حضور است — با بسته‌های اقتصادی مخصوص شهرهای کوچک استان.']],
